
const L={state:null,profile:null,views:{},utils:{},config:{}};
L.config.viewMap={dashboard:{icon:"📊",title:"Dashboard"},profile:{icon:"👤",title:"Perfil"},goals:{icon:"🎯",title:"Objetivos"},habits:{icon:"💪",title:"Hábitos"},tasks:{icon:"✅",title:"Tareas"},schedule:{icon:"📅",title:"Horario"},nutrition:{icon:"🍎",title:"Nutrición"},training:{icon:"🏋️",title:"Entrenamiento"},finance:{icon:"💰",title:"Finanzas"},shopping:{icon:"🛒",title:"Compras"},inventory:{icon:"📦",title:"Inventario"},supplements:{icon:"💊",title:"Suplementos"},skincare:{icon:"🧴",title:"Skincare"},hair:{icon:"💇",title:"Cabello"},developer:{icon:"💻",title:"Developer"},settings:{icon:"⚙️",title:"Ajustes"}};
L.config.bottomNav=["dashboard","tasks","habits","nutrition","finance"];
L.shopCat={Comida:"🍔",Aseo:"🧴",Hogar:"🏠",Salud:"💊",Ropa:"👕",Tecnologia:"🔌",Mascotas:"🐾",Estudio:"📚",Otro:"📦"};
L.utils.uuid=()=>`${Date.now().toString(36)}${Math.random().toString(36).slice(2,8)}`;
L.utils.todayKey=()=>new Date().toISOString().slice(0,10);
L.utils.today=()=>new Date().toLocaleDateString("es-ES");
L.utils.formatCurrency=a=>{const c=L.state.finance?.currency||"COP";return new Intl.NumberFormat("es-CO",{style:"currency",currency:c,maximumFractionDigits:0}).format(a||0)};
L.utils.imc=(w,h)=>{if(!w||!h)return"—";const m=h/100;return(w/(m*m)).toFixed(1)};
L.utils.imcStatus=v=>{const n=parseFloat(v);if(isNaN(n))return{label:"",color:"var(--text3)"};if(n<18.5)return{label:"Bajo peso",color:"var(--warning)"};if(n<25)return{label:"Normal",color:"var(--success)"};if(n<30)return{label:"Sobrepeso",color:"var(--warning)"};return{label:"Obesidad",color:"var(--danger)"}};
L.utils.calcAge=bd=>{if(!bd)return null;return Math.floor((Date.now()-new Date(bd).getTime())/(1000*60*60*24*365.25))};
L.utils.percent=(c,t)=>t?Math.min(100,Math.round((c/t)*100)):0;
L.utils.esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
L.utils.toast=msg=>{const t=document.getElementById("toast");t.textContent=msg;t.classList.add("show");clearTimeout(L._toastT);L._toastT=setTimeout(()=>t.classList.remove("show"),2200)};
L.utils.last7Days=()=>{const a=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);a.push(d.toISOString().slice(0,10))}return a};
L.utils.bar=(p,cls)=>{const v=Math.min(100,Math.max(0,p||0));return`<div class="progress"><div class="fill-${cls||'primary'}" style="width:${v}%"></div></div>`};
L.utils.macroCls=(cur,goal)=>{const p=L.utils.percent(cur||0,goal||1);if(p>=100)return"danger";if(p>=85)return"warning";return"success"};
L.save=()=>localStorage.setItem("lifeos_state",JSON.stringify(L.state));
L.loadCache=()=>{const s=localStorage.getItem("lifeos_state");return s?JSON.parse(s):null};
L.loadProfile=async()=>{try{const r=await fetch("life_profile.json",{cache:"no-store"});if(!r.ok)throw 0;L.profile=await r.json()}catch(e){const c=L.loadCache();if(c)L.profile=c;else L.profile={metadata:{app:"LifeOS",version:"2.0.0"},profile:{},finance:{categories:[],savingsGoals:[]},nutrition:{foods:[]},training:{exercises:[],history:[],sessions:[],gymDays:{},restDays:{}},shopping:[],habits:[],goals:[],tasks:[],schedule:{},skincare:{amSteps:[],pmSteps:[],log:{}},hair:{steps:[]},supplements:[],developer:{},settings:{},inventory:[]}}const c=L.loadCache();L.state=L.mergeDeep(JSON.parse(JSON.stringify(L.profile)),c||{});L.migrate();L.save()};
L.mergeDeep=(t,s)=>{for(const k in s){if(s[k]&&typeof s[k]==="object"&&!Array.isArray(s[k])){if(!t[k])t[k]={};L.mergeDeep(t[k],s[k])}else if(s[k]!==undefined)t[k]=s[k]}return t};
L.migrate=()=>{const s=L.state,n=s.nutrition||(s.nutrition={});if(n.lastDate!==L.utils.todayKey()){n.todayCalories=0;n.todayProtein=0;n.todayCarbs=0;n.todayFat=0;n.meals=[];n.lastDate=L.utils.todayKey()}const f=s.finance||(s.finance={});if(!f.categories||!f.categories.length)f.categories=[{id:"cat1",name:"Comida",icon:"🍔"},{id:"cat2",name:"Transporte",icon:"🚗"},{id:"cat3",name:"Hogar",icon:"🏠"},{id:"cat4",name:"Salud",icon:"💊"},{id:"cat5",name:"Ocio",icon:"🎮"}];if(!f.savingsGoals)f.savingsGoals=[];if(!f.travel)f.travel=s.travel||[];if(!s.skincare.amSteps){s.skincare.amSteps=(s.skincare.steps||[]).filter(x=>x.period!=="Noche").map(x=>x.name);s.skincare.pmSteps=(s.skincare.steps||[]).filter(x=>x.period!=="Mañana").map(x=>x.name);s.skincare.log=s.skincare.log||{}}(s.tasks||[]).forEach(t=>{if(!t.category)t.category="Personal"});(s.shopping||[]).forEach(i=>{if(!i.category)i.category="Otro"});if(!s.training.sessions)s.training.sessions=[];if(!s.training.gymDays)s.training.gymDays={};if(!s.training.restDays)s.training.restDays={};if(!s.training.exerciseDefs)s.training.exerciseDefs={};delete s.profile.goal};
L.router=v=>{L.currentView=v;document.querySelectorAll("nav.bottom button").forEach(b=>b.classList.toggle("active",b.dataset.view===v));document.querySelectorAll(".sheet-grid button").forEach(b=>b.classList.toggle("active",b.dataset.view===v));const c=L.config.viewMap[v]||{title:v};document.getElementById("title").textContent=c.title;const r=document.getElementById("content");r.innerHTML="";r.scrollTop=0;if(L.views[v])L.views[v](r);else r.innerHTML=`<div class="card"><h2>${c.title}</h2><p class="empty">Vista en construcción</p></div>`;L.closeMenu()};
L.buildBottomNav=()=>{document.getElementById("bottomNav").innerHTML=L.config.bottomNav.map(k=>{const c=L.config.viewMap[k];return`<button data-view="${k}" onclick="L.router('${k}')"><span class="ic">${c.icon}</span>${c.title}</button>`}).join("")+`<button onclick="L.openMenu()"><span class="ic">⋯</span>Más</button>`};
L.openMenu=()=>{const p=L.state.profile||{},i=(p.name?.[0]||"")+(p.lastname?.split(" ")[0]?.[0]||"");const it=Object.entries(L.config.viewMap).map(([k,c])=>`<button data-view="${k}" onclick="L.router('${k}')"><span class="ic">${c.icon}</span>${c.title}</button>`).join("");document.getElementById("menuSheet").innerHTML=`<div class="sheet-handle"></div><div class="profile-strip"><div class="avatar">${i||"👤"}</div><div><div style="font-weight:700">${p.name||"Usuario"} ${p.lastname?.split(" ")[0]||""}</div><div style="font-size:12px;color:var(--text3)">${p.profession||"LifeOS"}</div></div></div><h3>Navegación</h3><div class="sheet-grid">${it}</div>`;document.getElementById("menuSheet").style.display="block";document.getElementById("sheetOverlay").classList.add("open")};
L.closeMenu=()=>{document.getElementById("sheetOverlay").classList.remove("open");document.getElementById("menuSheet").style.display="none"};
L.card=(t,c,e="")=>`<div class="card"><h2>${t}${e?`<span class="subtitle">${e}</span>`:""}</h2>${c}</div>`;
L.badge=(t,y="primary")=>`<span class="badge badge-${y}">${t}</span>`;
L.metricHtml=(l,v,p,cls)=>`<div class="metric"><div class="mlabel">${l}</div><div class="mval">${v}</div>${L.utils.bar(p,cls)}</div>`;
L.views.dashboard=r=>{const s=L.state,p=s.profile||{},n=s.nutrition||{},f=s.finance||{},dev=s.developer||{},goals=s.goals||[],habits=s.habits||[],tasks=s.tasks||[];const cg=goals.filter(g=>g.done).length,th=habits.filter(h=>(h.completedDates||[]).includes(L.utils.todayKey())).length,tt=tasks.filter(t=>t.done).length;const ft=(f.fixedExpenses||[]).reduce((a,i)=>a+(i.price||0),0),st=(f.subscriptions||[]).reduce((a,i)=>a+(i.price||0),0);const mo=ft+st,bal=(f.monthlyIncome||0)-mo;const imc=L.utils.imc(p.weight,p.height),imcInfo=L.utils.imcStatus(imc);const np=L.utils.percent(n.todayCalories||0,n.goals?.calories||2300);const initials=(p.name?.[0]||"")+(p.lastname?.split(" ")[0]?.[0]||"");r.innerHTML=`<div class="card"><div class="profile-strip"><div class="avatar-lg avatar">${initials||"👤"}</div><div style="min-width:0;flex:1"><div style="font-weight:700;font-size:17px">${p.name||"Usuario"} ${p.lastname||""}</div><div style="font-size:12px;color:var(--text3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${p.profession||"—"} · ${p.city||""}</div></div></div><div class="pill-stats"><div class="pill"><b>${p.weight||"—"}</b>kg</div><div class="pill"><b style="color:${imcInfo.color}">${imc}</b>${imcInfo.label||"IMC"}</div><div class="pill"><b>${p.targetWeight||"—"}</b>meta kg</div></div></div><div class="metric-grid">${L.metricHtml("Objetivos",`${cg}/${goals.length}`,L.utils.percent(cg,goals.length||1),"primary")}${L.metricHtml("Hábitos hoy",`${th}/${habits.length}`,L.utils.percent(th,habits.length||1),"success")}${L.metricHtml("Tareas",`${tt}/${tasks.length}`,L.utils.percent(tt,tasks.length||1),"warning")}${L.metricHtml("Balance",L.utils.formatCurrency(bal),L.utils.percent(mo,f.monthlyIncome||1),bal<0?"danger":"success")}${L.metricHtml("Calorías",`${n.todayCalories||0}/${n.goals?.calories||0}`,np,L.utils.macroCls(n.todayCalories,n.goals?.calories))}${L.metricHtml("Proteína",`${(n.todayProtein||0).toFixed(0)}g`,L.utils.percent(n.todayProtein||0,n.goals?.protein||1),"success")}</div>${L.card("Próximos viajes",(f.travel||[]).length===0?'<p class="empty">Sin viajes planeados</p>':(f.travel||[]).slice(0,3).map(t=>`<div class="list-row"><div class="grow"><div class="t1">🌍 ${L.utils.esc(t.country)}${t.city?` · ${L.utils.esc(t.city)}`:""}</div><div class="t2">${t.status}</div></div>${L.badge(t.priority,t.priority==="Alta"?"danger":t.priority==="Media"?"warning":"info")}</div>`).join(""))}${L.card("Gastos fijos & suscripciones",`<table style="width:100%;font-size:13px"><tr><td>Fijos</td><td style="text-align:right">${L.utils.formatCurrency(ft)}</td></tr><tr><td>Suscripciones</td><td style="text-align:right">${L.utils.formatCurrency(st)}</td></tr><tr style="border-top:1px solid var(--card3)"><td><strong>Total</strong></td><td style="text-align:right"><strong>${L.utils.formatCurrency(mo)}</strong></td></tr></table>`)}${(dev.projects||[]).length?L.card("Developer",dev.projects.map(pr=>`<div class="list-row"><div class="grow"><div class="t1">${L.utils.esc(pr.name)}</div>${L.utils.bar(pr.progress,"primary")}</div>${L.badge(pr.status,pr.status==="Completado"?"success":"primary")}</div>`).join("")):""}`};
L.views.profile=r=>{const p=L.state.profile||{},age=L.utils.calcAge(p.birthDate),imc=L.utils.imc(p.weight,p.height),imcInfo=L.utils.imcStatus(imc),initials=(p.name?.[0]||"")+(p.lastname?.split(" ")[0]?.[0]||"");r.innerHTML=`${L.card("Perfil",`<div class="profile-strip"><div class="avatar-lg avatar">${initials||"👤"}</div><div><div style="font-weight:700;font-size:18px">${p.name||""} ${p.lastname||""}</div><div style="font-size:13px;color:var(--text3)">${p.profession||"Sin profesión"}</div><div style="font-size:13px;color:var(--text3)">${p.city||""}${p.country?", "+p.country:""}</div></div></div><div class="pill-stats"><div class="pill"><b>${p.height||"—"}</b>cm</div><div class="pill"><b>${p.weight||"—"}</b>kg</div><div class="pill"><b>${p.targetWeight||"—"}</b>meta</div><div class="pill"><b style="color:${imcInfo.color}">${imc}</b>${imcInfo.label||"IMC"}</div>${age?`<div class="pill"><b>${age}</b>años</div>`:""}</div>`)}${L.card("Editar datos",`<div class="form"><div class="form-row"><div><label>Nombre</label><input id="ep_name" value="${L.utils.esc(p.name||"")}"/></div><div><label>Apellidos</label><input id="ep_last" value="${L.utils.esc(p.lastname||"")}"/></div></div><div class="form-row"><div><label>País</label><input id="ep_country" value="${L.utils.esc(p.country||"")}"/></div><div><label>Ciudad</label><input id="ep_city" value="${L.utils.esc(p.city||"")}"/></div></div><div class="form-row"><div><label>Nacimiento</label><input id="ep_birth" type="date" value="${p.birthDate||""}"/></div><div><label>Profesión</label><input id="ep_prof" value="${L.utils.esc(p.profession||"")}"/></div></div><div class="form-row"><div><label>Altura (cm)</label><input id="ep_h" type="number" value="${p.height||""}"/></div><div><label>Peso (kg)</label><input id="ep_w" type="number" value="${p.weight||""}"/></div></div><div><label>Peso meta (kg)</label><input id="ep_tw" type="number" value="${p.targetWeight||""}"/></div><button class="primary" onclick="L.saveProfile()">💾 Guardar</button></div>`)}`};
L.saveProfile=()=>{const p=L.state.profile;p.name=document.getElementById("ep_name").value;p.lastname=document.getElementById("ep_last").value;p.country=document.getElementById("ep_country").value;p.city=document.getElementById("ep_city").value;p.birthDate=document.getElementById("ep_birth").value;p.profession=document.getElementById("ep_prof").value;p.height=+document.getElementById("ep_h").value||0;p.weight=+document.getElementById("ep_w").value||0;p.targetWeight=+document.getElementById("ep_tw").value||0;L.save();L.utils.toast("Perfil guardado");L.router("profile")};
L.views.goals=r=>{const g=L.state.goals||[],done=g.filter(x=>x.done).length;r.innerHTML=`<div class="card"><h2>Nuevo objetivo</h2><div class="form"><input id="g_title" placeholder="Nombre del objetivo"/><button class="primary" onclick="L.addGoal()">➕ Agregar</button></div></div><div class="card"><h2>Lista diaria <span class="subtitle">${done}/${g.length}</span></h2>${g.length===0?'<p class="empty">Sin objetivos aún</p>':g.map(x=>`<div class="checkbox-row ${x.done?'done':''}"><input type="checkbox" ${x.done?'checked':''} onchange="L.toggleGoal('${x.id}')"/><span class="editable clabel" contenteditable="true" onblur="L.renameGoal('${x.id}',this.textContent)">${L.utils.esc(x.title)}</span><span class="editable" contenteditable="true" style="width:38px;text-align:right;flex-shrink:0;font-size:12px;color:var(--primary)" onblur="L.setGoalPct('${x.id}',this.textContent)">${x.progress||0}</span><span style="font-size:11px;color:var(--text3);flex-shrink:0">%</span><button class="btn-icon" onclick="L.delGoal('${x.id}')">🗑</button></div>${L.utils.bar(x.progress||0,"primary")}`).join("")}</div>`};
L.addGoal=()=>{const t=document.getElementById("g_title").value.trim();if(!t)return;L.state.goals.push({id:L.utils.uuid(),title:t,progress:0,done:false});L.save();L.router("goals")};
L.toggleGoal=id=>{const g=L.state.goals.find(x=>x.id===id);if(g){g.done=!g.done;g.progress=g.done?100:g.progress}L.save();L.router("goals")};
L.renameGoal=(id,v)=>{const g=L.state.goals.find(x=>x.id===id);if(g)g.title=v.trim()||g.title;L.save()};
L.setGoalPct=(id,v)=>{const g=L.state.goals.find(x=>x.id===id);if(g){let n=Math.max(0,Math.min(100,+v.replace(/\D/g,'')||0));g.progress=n;g.done=n>=100}L.save();L.router("goals")};
L.delGoal=id=>{L.state.goals=L.state.goals.filter(x=>x.id!==id);L.save();L.router("goals")};
L.views.habits=r=>{const h=L.state.habits||[],tk=L.utils.todayKey(),days=L.utils.last7Days();const doneToday=h.filter(x=>(x.completedDates||[]).includes(tk)).length;r.innerHTML=`<div class="card"><h2>Nuevo hábito</h2><div class="form"><input id="h_name" placeholder="Nombre (ej: Leer 20 min)"/><button class="primary" onclick="L.addHabit()">➕ Agregar</button></div></div><div class="card"><h2>Hábitos <span class="subtitle">${doneToday}/${h.length} hoy</span></h2>${h.length===0?'<p class="empty">Sin hábitos aún</p>':h.map(x=>{const cd=x.completedDates||[],isDone=cd.includes(tk);let streak=0;for(let i=days.length-1;i>=0;i--){if(cd.includes(days[i]))streak++;else break}return`<div style="padding:10px 0;border-bottom:1px solid #2a313c"><div class="row-between"><span style="font-size:14px;font-weight:600">${L.utils.esc(x.name)}</span><div class="row"><span class="streak-pill">🔥${streak}</span><button class="btn-icon" onclick="L.toggleHabit('${x.id}')" style="font-size:20px">${isDone?'✅':'⬜'}</button><button class="btn-icon" onclick="L.delHabit('${x.id}')">🗑</button></div></div><div class="dot-row" style="margin-top:8px">${days.map(d=>`<div class="dot ${cd.includes(d)?'on':''} ${d===tk?'today':''}">${new Date(d).getDate()}</div>`).join("")}</div></div>`}).join("")}</div>`};
L.addHabit=()=>{const n=document.getElementById("h_name").value.trim();if(!n)return;L.state.habits.push({id:L.utils.uuid(),name:n,completedDates:[]});L.save();L.router("habits")};
L.toggleHabit=id=>{const h=L.state.habits.find(x=>String(x.id)===String(id));if(!h)return;if(!h.completedDates)h.completedDates=[];const tk=L.utils.todayKey();const i=h.completedDates.indexOf(tk);if(i>=0)h.completedDates.splice(i,1);else h.completedDates.push(tk);L.save();L.router("habits")};
L.delHabit=id=>{L.state.habits=L.state.habits.filter(x=>String(x.id)!==String(id));L.save();L.router("habits")};
L.taskCatIcon={Universidad:"🎓",Casa:"🏠",Hogar:"🧹",Trabajo:"💼",Personal:"🙋",Otro:"📌"};
L.notifCheckStarted=false;
L.calEvents=()=>L.state.calendar||(L.state.calendar={events:[]});
L.startNotifLoop=()=>{if(L.notifCheckStarted)return;L.notifCheckStarted=true;setInterval(()=>{if(typeof Notification==="undefined"||Notification.permission!=="granted")return;const now=Date.now();(L.state.tasks||[]).forEach(t=>{if(t.done||t.notified||!t.due||!t.dueTime)return;const dt=new Date(`${t.due}T${t.dueTime}`).getTime();if(dt-now<=0&&dt-now>-3600000){new Notification("📌 Tarea pendiente",{body:t.title,tag:t.id});t.notified=true;L.save()}});(L.calEvents().events||[]).forEach(e=>{if(e.notified||!e.date)return;const dt=new Date(`${e.date}T${e.time||"08:00"}`).getTime();if(dt-now<=0&&dt-now>-3600000){new Notification(`${e.icon||"🔔"} ${e.title}`,{tag:e.id});e.notified=true;L.save()}})},60000)};
L.views.tasks=r=>{const t=L.state.tasks||[],done=t.filter(x=>x.done).length;const perm=typeof Notification!=="undefined"?Notification.permission:"unsupported";r.innerHTML=`${perm==="granted"?"":`<div class="card"><div class="row-between"><div><div style="font-weight:600;font-size:13px">🔔 Notificaciones</div><div style="font-size:11px;color:var(--text3)">Actívalas para avisos de tareas</div></div><button class="primary btn-sm" onclick="L.reqNotif()">Activar</button></div></div>`}<div class="card"><h2>Nueva tarea</h2><div class="form"><input id="t_title" placeholder="Título"/><div class="form-row"><input id="t_due" type="date"/><input id="t_time" type="time"/></div><div class="form-row"><select id="t_pri"><option value="Baja">🟢 Baja</option><option value="Media" selected>🟡 Media</option><option value="Alta">🔴 Alta</option></select><select id="t_cat">${Object.keys(L.taskCatIcon).map(c=>`<option value="${c}">${L.taskCatIcon[c]} ${c}</option>`).join("")}</select></div><button class="primary" onclick="L.addTask()">➕ Crear</button></div></div><div class="card"><h2>Tareas <span class="subtitle">${done}/${t.length}</span></h2>${t.length===0?'<p class="empty">Sin tareas</p>':t.map(x=>`<div class="checkbox-row ${x.done?'done':''}"><input type="checkbox" ${x.done?'checked':''} onchange="L.toggleTask('${x.id}')"/><span class="clabel">${L.taskCatIcon[x.category]||"📌"} ${L.utils.esc(x.title)}${x.due?`<br><span style="font-size:11px;color:var(--text3)">${x.due}${x.dueTime?' · '+x.dueTime:''}</span>`:''}</span>${L.badge(x.priority,x.priority==="Alta"?"danger":x.priority==="Media"?"warning":"success")}<button class="btn-icon" onclick="L.delTask('${x.id}')">🗑</button></div>`).join("")}</div>`};
L.reqNotif=()=>{if(typeof Notification==="undefined"){L.utils.toast("No disponible");return}Notification.requestPermission().then(p=>{if(p==="granted"){L.startNotifLoop();L.utils.toast("Notificaciones activadas")}L.router("tasks")})};
L.addTask=()=>{const t=document.getElementById("t_title").value.trim(),d=document.getElementById("t_due").value,tm=document.getElementById("t_time").value,p=document.getElementById("t_pri").value,c=document.getElementById("t_cat").value;if(!t)return;L.state.tasks.push({id:L.utils.uuid(),title:t,done:false,created:L.utils.today(),due:d,dueTime:tm,priority:p,category:c,notified:false});L.save();L.router("tasks")};
L.toggleTask=id=>{const t=L.state.tasks.find(x=>x.id===id);if(t)t.done=!t.done;L.save();L.router("tasks")};
L.delTask=id=>{L.state.tasks=L.state.tasks.filter(x=>x.id!==id);L.save();L.router("tasks")};
L.scheduleDay=L.scheduleDay||"monday";
L.views.schedule=r=>{const days=[{k:"monday",l:"Lun"},{k:"tuesday",l:"Mar"},{k:"wednesday",l:"Mié"},{k:"thursday",l:"Jue"},{k:"friday",l:"Vie"},{k:"saturday",l:"Sáb"},{k:"sunday",l:"Dom"}],cur=L.scheduleDay;const dayNames={monday:"Lunes",tuesday:"Martes",wednesday:"Miércoles",thursday:"Jueves",friday:"Viernes",saturday:"Sábado",sunday:"Domingo"};r.innerHTML=`<div class="chip-row">${days.map(d=>`<button class="chip ${cur===d.k?'active':''}" onclick="L.scheduleDay='${d.k}';L.router('schedule')">${d.l}</button>`).join("")}</div><div class="card"><h2>${dayNames[cur]}</h2><textarea id="sch_ta" rows="10" placeholder="08:00 Gimnasio&#10;10:00 Clases&#10;14:00 Trabajo..." onblur="L.saveSched()">${L.state.schedule?.[cur]||""}</textarea></div>`};
L.saveSched=()=>{L.state.schedule[L.scheduleDay]=document.getElementById("sch_ta").value;L.save();L.utils.toast("Horario guardado")};
L.views.nutrition=r=>{const n=L.state.nutrition||{},g=n.goals||{calories:2300,protein:180,carbs:220,fat:70},inv=L.state.inventory||[];r.innerHTML=`<div class="card"><h2>Metas de hoy</h2><div class="macro-bar"><div class="macro-header"><span>🔥 ${n.todayCalories||0}/${g.calories} kcal</span></div>${L.utils.bar(L.utils.percent(n.todayCalories||0,g.calories),L.utils.macroCls(n.todayCalories,g.calories))}</div><div class="macro-bar"><div class="macro-header"><span>🥩 ${(n.todayProtein||0).toFixed(0)}/${g.protein}g prot</span></div>${L.utils.bar(L.utils.percent(n.todayProtein||0,g.protein),L.utils.macroCls(n.todayProtein,g.protein))}</div><div class="macro-bar"><div class="macro-header"><span>🍞 ${(n.todayCarbs||0).toFixed(0)}/${g.carbs}g carbs</span></div>${L.utils.bar(L.utils.percent(n.todayCarbs||0,g.carbs),L.utils.macroCls(n.todayCarbs,g.carbs))}</div><div class="macro-bar" style="margin-bottom:0"><div class="macro-header"><span>🥑 ${(n.todayFat||0).toFixed(0)}/${g.fat}g fat</span></div>${L.utils.bar(L.utils.percent(n.todayFat||0,g.fat),L.utils.macroCls(n.todayFat,g.fat))}</div></div><div class="card"><h2>Registrar comida</h2><div class="form"><select id="nf_sel"><option value="">— Alimento —</option>${(n.foods||[]).map(f=>`<option value="${f.id}">${L.utils.esc(f.name)} (${f.calories}kcal)${f.inventoryId?' 📦':''}</option>`).join("")}</select><input id="nf_qty" type="number" value="1" min="0.5" step="0.5"/><button class="success" onclick="L.addMeal()">➕ Agregar</button></div></div><div class="card"><h2>Comidas hoy</h2>${(n.meals||[]).length===0?'<p class="empty">Sin comidas registradas</p>':(n.meals||[]).map((m,i)=>`<div class="list-row"><div class="grow"><div class="t1">${L.utils.esc(m.name)} ×${m.qty}</div><div class="t2">${m.calories}kcal · ${m.protein}gP · ${m.carbs}gC · ${m.fat}gF</div></div><button class="btn-icon" onclick="L.delMeal(${i})">🗑</button></div>`).join("")}</div><div class="card"><h2>Base de alimentos</h2><div class="form"><input id="nf_name" placeholder="Nombre"/><div class="form-row"><input id="nf_cal" type="number" placeholder="Cal"/><input id="nf_prot" type="number" placeholder="Prot (g)"/></div><div class="form-row"><input id="nf_carbs" type="number" placeholder="Carbs (g)"/><input id="nf_fat" type="number" placeholder="Fat (g)"/></div><label>Vincular a inventario (opcional)</label><select id="nf_inv"><option value="">— Ninguno —</option>${inv.map(i=>`<option value="${i.id}">${L.utils.esc(i.name)} (${i.qty})</option>`).join("")}</select><button class="primary" onclick="L.addFood()">Agregar alimento</button></div>${(n.foods||[]).length?`<div style="margin-top:10px">${(n.foods||[]).map(f=>`<div class="list-row"><div class="grow"><div class="t1">${L.utils.esc(f.name)}${f.inventoryId?' 📦':''}</div><div class="t2">${f.calories}kcal · ${f.protein}gP · ${f.carbs}gC · ${f.fat}gF</div></div><button class="btn-icon" onclick="L.delFood('${f.id}')">🗑</button></div>`).join("")}</div>`:''}</div>`};
L.addMeal=()=>{const fid=document.getElementById("nf_sel").value,qty=+document.getElementById("nf_qty").value||1;if(!fid)return;const food=(L.state.nutrition.foods||[]).find(f=>String(f.id)===String(fid));if(!food)return;const n=L.state.nutrition;if(!n.meals)n.meals=[];n.meals.push({name:food.name,qty,calories:Math.round(food.calories*qty),protein:+(food.protein*qty).toFixed(1),carbs:+(food.carbs*qty).toFixed(1),fat:+(food.fat*qty).toFixed(1)});n.todayCalories=(n.todayCalories||0)+Math.round(food.calories*qty);n.todayProtein=(n.todayProtein||0)+food.protein*qty;n.todayCarbs=(n.todayCarbs||0)+food.carbs*qty;n.todayFat=(n.todayFat||0)+food.fat*qty;if(food.inventoryId){const it=(L.state.inventory||[]).find(i=>i.id===food.inventoryId);if(it)it.qty=Math.max(0,(it.qty||0)-qty)}L.save();L.router("nutrition")};
L.delMeal=i=>{const n=L.state.nutrition,m=n.meals[i];if(m){n.todayCalories=Math.max(0,(n.todayCalories||0)-m.calories);n.todayProtein=Math.max(0,(n.todayProtein||0)-m.protein);n.todayCarbs=Math.max(0,(n.todayCarbs||0)-m.carbs);n.todayFat=Math.max(0,(n.todayFat||0)-m.fat);n.meals.splice(i,1)}L.save();L.router("nutrition")};
L.addFood=()=>{const name=document.getElementById("nf_name").value.trim(),cal=+document.getElementById("nf_cal").value||0,prot=+document.getElementById("nf_prot").value||0,carbs=+document.getElementById("nf_carbs").value||0,fat=+document.getElementById("nf_fat").value||0,invId=document.getElementById("nf_inv").value||null;if(!name)return;const n=L.state.nutrition;if(!n.foods)n.foods=[];n.foods.push({id:L.utils.uuid(),name,protein:prot,carbs,fat,calories:cal,inventoryId:invId});L.save();L.router("nutrition")};
L.delFood=id=>{L.state.nutrition.foods=(L.state.nutrition.foods||[]).filter(f=>f.id!==id);L.save();L.router("nutrition")};
L.timerState={mode:"timer",running:false,remaining:0,elapsed:0,handle:null};
L.views.training=r=>{const t=L.state.training||{},ts=L.timerState,fmt=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;const tk=L.utils.todayKey();const todaySesh=(t.sessions||[]).filter(s=>s.date===tk);const exs=t.exercises||[];const defs=t.exerciseDefs||{};r.innerHTML=`<div class="card"><h2>⏱ Temporizador</h2><div class="timer-display" id="timerDisp">${fmt(ts.remaining)}</div><div class="timer-btns"><button class="success" onclick="L.timerStart()">▶ Iniciar</button><button class="warning" onclick="L.timerPause()">⏸ Pausar</button><button class="danger" onclick="L.timerReset()">⏹ Reset</button></div><div class="preset-row"><button class="ghost btn-sm" onclick="L.timerPreset(30)">30s</button><button class="ghost btn-sm" onclick="L.timerPreset(60)">60s</button><button class="ghost btn-sm" onclick="L.timerPreset(90)">90s</button><button class="ghost btn-sm" onclick="L.timerPreset(180)">3min</button><button class="ghost btn-sm" onclick="L.timerPreset(300)">5min</button></div></div><div class="card"><h2>📅 Días de entreno</h2><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">${["Lun","Mar","Mié","Jue","Vie","Sáb","Dom"].map((d,i)=>{const dk=["monday","tuesday","wednesday","thursday","friday","saturday","sunday"][i];const isGym=t.gymDays?.[dk],isRest=t.restDays?.[dk];let cls="gym-day-btn";if(isGym)cls+=" active";if(isRest)cls+=" rest";return`<button class="${cls}" onclick="L.toggleGymDay('${dk}')">${d}</button>`}).join("")}</div><p style="font-size:11px;color:var(--text3)">Toca para marcar gym (azul) o doble toca para descanso (rojo)</p></div><div class="card"><h2>💪 Ejercicios del día</h2><div class="form"><select id="tr_s_ex"><option value="">— Ejercicio —</option>${exs.map(ex=>`<option value="${ex.id}">${L.utils.esc(ex.name)}</option>`).join("")}</select><div class="form-row"><input id="tr_s_sets" type="number" placeholder="Series"/><input id="tr_s_reps" type="number" placeholder="Reps x serie"/></div><div class="form-row"><input id="tr_s_w" type="number" placeholder="Peso kg"/><input id="tr_s_dur" type="number" placeholder="Minutos"/></div><div class="form-row"><input id="tr_s_rir" type="number" placeholder="RIR (0-5)" min="0" max="5"/><input id="tr_s_notes" placeholder="Notas"/></div><button class="success" onclick="L.addSession()">💾 Guardar sesión</button></div><div style="margin-top:12px">${todaySesh.length===0?'<p class="empty">Sin sesiones hoy</p>':todaySesh.map((h,i)=>{const def=defs[h.exerciseId]||{};return`<div class="sesh-row"><div class="sesh-title">${L.utils.esc(h.exerciseName)} ${h.done?'✅':''}</div><div class="sesh-meta">${[h.sets&&h.sets+" series",h.reps&&h.reps+" reps",h.weight&&h.weight+"kg",h.duration&&h.duration+"min",h.rir&&"RIR "+h.rir].filter(Boolean).join(" · ")}</div>${def.description?`<div class="sesh-desc">${L.utils.esc(def.description)}</div>`:""}<div class="sesh-stats">${def.muscles?`<span>💪 ${def.muscles}</span>`:""}${def.equipment?`<span>🛠 ${def.equipment}</span>`:""}${def.difficulty?`<span>📊 ${def.difficulty}</span>`:""}</div><div class="row" style="margin-top:8px"><button class="ghost btn-sm" onclick="L.toggleSeshDone(${i})">${h.done?'↩ Desmarcar':'✅ Completado'}</button><button class="btn-icon" onclick="L.delSesh(${i})">🗑</button></div></div>`}).reverse().join("")}</div></div><div class="card"><h2>🏋️ Ejercicios</h2><div class="form"><input id="tr_exname" placeholder="Nombre"/><select id="tr_extype"><option value="Cardio">Cardio</option><option value="Fuerza">Fuerza</option><option value="Core">Core</option><option value="Funcional">Funcional</option></select><input id="tr_exdesc" placeholder="Descripción de ejecución"/><div class="form-row"><input id="tr_exmuscles" placeholder="Músculos"/><input id="tr_exequip" placeholder="Equipo"/></div><div class="form-row"><input id="tr_exdiff" placeholder="Dificultad"/><input id="tr_exvideo" placeholder="URL video (opcional)"/></div><button class="primary" onclick="L.addEx()">Agregar ejercicio</button></div><div style="margin-top:10px">${exs.map(ex=>{const d=defs[ex.id]||{};return`<div class="exercise-card"><div class="row" style="min-width:0"><div class="exercise-type ${ex.type.toLowerCase()}"></div><div style="min-width:0"><div style="font-weight:600;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${L.utils.esc(ex.name)}</div><div style="font-size:11px;color:var(--text3)">${ex.type}${d.muscles?` · ${d.muscles}`:""}</div></div></div><button class="btn-icon" onclick="L.delEx(${ex.id})">🗑</button></div>`}).join("")}</div></div>`};
L.timerPreset=s=>{L.timerState.remaining=s;L.timerTick()};
L.timerTick=()=>{const d=document.getElementById("timerDisp");if(!d)return;const ts=L.timerState;const fmt=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,'0')}`;d.textContent=fmt(ts.remaining)};
L.timerStart=()=>{const ts=L.timerState;if(ts.running)return;ts.running=true;ts.handle=setInterval(()=>{ts.remaining--;if(ts.remaining<=0){ts.remaining=0;L.timerPause();if(typeof Notification!=="undefined"&&Notification.permission==="granted")new Notification("⏱ Tiempo terminado");L.utils.toast("⏱ Tiempo terminado")}L.timerTick()},1000)};
L.timerPause=()=>{const ts=L.timerState;ts.running=false;if(ts.handle)clearInterval(ts.handle);ts.handle=null};
L.timerReset=()=>{L.timerPause();L.timerState.remaining=0;L.timerTick()};
L.addEx=()=>{const name=document.getElementById("tr_exname").value.trim(),type=document.getElementById("tr_extype").value,desc=document.getElementById("tr_exdesc").value.trim(),muscles=document.getElementById("tr_exmuscles").value.trim(),equipment=document.getElementById("tr_exequip").value.trim(),difficulty=document.getElementById("tr_exdiff").value.trim(),video=document.getElementById("tr_exvideo").value.trim();if(!name)return;const t=L.state.training;if(!t.exercises)t.exercises=[];const maxId=t.exercises.reduce((m,e)=>Math.max(m,e.id||0),0);const newId=maxId+1;t.exercises.push({id:newId,name,type});if(!t.exerciseDefs)t.exerciseDefs={};t.exerciseDefs[newId]={description:desc,muscles,equipment,difficulty,video};L.save();L.router("training")};
L.delEx=id=>{const t=L.state.training;t.exercises=(t.exercises||[]).filter(e=>e.id!==id);delete(t.exerciseDefs||{})[id];L.save();L.router("training")};
L.addSession=()=>{const eid=document.getElementById("tr_s_ex").value;if(!eid)return;const t=L.state.training,ex=(t.exercises||[]).find(e=>String(e.id)===String(eid));if(!ex)return;if(!t.sessions)t.sessions=[];t.sessions.push({id:L.utils.uuid(),exerciseId:ex.id,exerciseName:ex.name,sets:+document.getElementById("tr_s_sets").value||null,reps:+document.getElementById("tr_s_reps").value||null,weight:+document.getElementById("tr_s_w").value||null,duration:+document.getElementById("tr_s_dur").value||null,rir:+document.getElementById("tr_s_rir").value||null,notes:document.getElementById("tr_s_notes").value.trim(),date:L.utils.todayKey(),done:false});L.save();L.router("training")};
L.toggleSeshDone=i=>{const t=L.state.training,tk=L.utils.todayKey();const today=(t.sessions||[]).filter(s=>s.date===tk);if(today[i])today[i].done=!today[i].done;L.save();L.router("training")};
L.delSesh=i=>{const t=L.state.training,tk=L.utils.todayKey();const arr=(t.sessions||[]).filter(s=>s.date===tk);if(arr[i]){const all=t.sessions||[];const idx=all.indexOf(arr[i]);if(idx>=0)all.splice(idx,1)}L.save();L.router("training")};
L.toggleGymDay=dk=>{const t=L.state.training;if(!t.gymDays)t.gymDays={};if(!t.restDays)t.restDays={};if(t.gymDays[dk]){t.gymDays[dk]=false;t.restDays[dk]=true}else if(t.restDays[dk]){t.restDays[dk]=false}else{t.gymDays[dk]=true}L.save();L.router("training")};
L.financeTab=L.financeTab||"overview";
L.views.finance=r=>{const f=L.state.finance||{},cur=f.currency||"COP",ft=(f.fixedExpenses||[]).reduce((a,i)=>a+(i.price||0),0),st=(f.subscriptions||[]).reduce((a,i)=>a+(i.price||0),0),dt=(f.debts||[]).reduce((a,i)=>a+((i.amount||0)-(i.paid||0)),0),svTotal=(f.savingsGoals||[]).reduce((a,i)=>a+(i.saved||0),0),mo=ft+st,bal=(f.monthlyIncome||0)-mo;const mkTab=(k,l)=>`<button class="${L.financeTab===k?'active':''}" onclick="L.financeTab='${k}';L.router('finance')">${l}</button>`;const tabs=`<div class="tabs">${mkTab("overview","Resumen")}${mkTab("movements","Gastos")}${mkTab("categories","Categorías")}${mkTab("savings","Ahorros")}${mkTab("fixed","Fijos")}${mkTab("subs","Subs")}${mkTab("debts","Deudas")}${mkTab("travel","Viajes")}</div>`;let body="";if(L.financeTab==="movements"){body=`<div class="card"><h2>Nuevo gasto</h2><div class="form"><input id="fm_concept" placeholder="Concepto"/><div class="form-row"><input id="fm_amount" type="number" placeholder="Monto"/><select id="fm_cat">${(f.categories||[]).map(c=>`<option value="${c.id}">${c.icon} ${L.utils.esc(c.name)}</option>`).join("")}</select></div><select id="fm_type"><option value="expense">💸 Gasto</option><option value="income">💰 Ingreso</option></select><button class="success" onclick="L.addFinMove()">Guardar</button></div></div><div class="card"><h2>Movimientos</h2>${(f.movements||[]).length===0?'<p class="empty">Sin movimientos</p>':(f.movements||[]).slice().reverse().map(m=>{const cat=(f.categories||[]).find(c=>c.id===m.catId);return`<div class="list-row"><div class="grow"><div class="t1">${cat?cat.icon+' ':''}${L.utils.esc(m.title)}</div><div class="t2">${m.date}</div></div>${L.badge(L.utils.formatCurrency(m.amount),m.type==='income'?'success':'danger')}<button class="btn-icon" onclick="L.delFinMove('${m.id}')">🗑</button></div>`}).join("")}</div>`}else if(L.financeTab==="categories"){body=`<div class="card"><h2>Nueva categoría</h2><div class="form"><div class="form-row"><input id="fcat_icon" placeholder="🙂 emoji" maxlength="4"/><input id="fcat_name" placeholder="Nombre"/></div><p style="font-size:11px;color:var(--text3)">Toca el campo emoji y usa el teclado de emojis de tu teléfono</p><button class="primary" onclick="L.addFinCat()">Agregar</button></div></div><div class="card"><h2>Categorías</h2>${(f.categories||[]).map(c=>{const spent=(f.movements||[]).filter(m=>m.catId===c.id&&m.type==='expense').reduce((a,m)=>a+m.amount,0);return`<div class="list-row"><div class="grow"><div class="t1">${c.icon} ${L.utils.esc(c.name)}</div><div class="t2">${L.utils.formatCurrency(spent)} gastado</div></div><button class="btn-icon" onclick="L.delFinCat('${c.id}')">🗑</button></div>`}).join("")}</div>`}else if(L.financeTab==="savings"){body=`<div class="card"><h2>Nueva meta de ahorro</h2><div class="form"><input id="fsv_name" placeholder="Nombre (ej: Vacaciones)"/><div class="form-row"><input id="fsv_target" type="number" placeholder="Meta"/><input id="fsv_saved" type="number" placeholder="Ahorrado" value="0"/></div><button class="primary" onclick="L.addSaving()">Agregar</button></div></div><div class="card"><h2>Ahorros <span class="subtitle">${L.utils.formatCurrency(svTotal)}</span></h2>${(f.savingsGoals||[]).length===0?'<p class="empty">Sin metas de ahorro</p>':(f.savingsGoals||[]).map(sv=>`<div style="padding:8px 0;border-bottom:1px solid #2a313c"><div class="row-between"><span style="font-weight:600;font-size:14px">${L.utils.esc(sv.name)}</span><button class="btn-icon" onclick="L.delSaving('${sv.id}')">🗑</button></div><div class="t2">${L.utils.formatCurrency(sv.saved)} / ${L.utils.formatCurrency(sv.target)}</div>${L.utils.bar(L.utils.percent(sv.saved,sv.target),"success")}<div class="row" style="margin-top:6px"><input type="number" placeholder="+monto" id="fsv_add_${sv.id}" style="flex:1"/><button class="btn-sm success" onclick="L.addToSaving('${sv.id}')">Añadir</button></div></div>`).join("")}</div>`}else if(L.financeTab==="fixed"){body=`<div class="card"><h2>Nuevo fijo</h2><div class="form"><input id="ff_name" placeholder="Nombre"/><div class="form-row"><input id="ff_price" type="number" placeholder="Monto"/><input id="ff_day" type="number" placeholder="Día" min="1" max="31"/></div><button class="primary" onclick="L.addFixed()">Agregar</button></div></div><div class="card"><h2>Gastos fijos <span class="subtitle">${L.utils.formatCurrency(ft)}</span></h2>${(f.fixedExpenses||[]).map(e=>`<div class="list-row"><div class="grow"><div class="t1">${L.utils.esc(e.name)}</div><div class="t2">Día ${e.day}</div></div><span>${L.utils.formatCurrency(e.price)}</span><button class="btn-icon" onclick="L.delFixed('${L.utils.esc(e.name)}')">🗑</button></div>`).join("")}</div>`}else if(L.financeTab==="subs"){body=`<div class="card"><h2>Nueva suscripción</h2><div class="form"><input id="fs_name" placeholder="Nombre"/><div class="form-row"><input id="fs_price" type="number" placeholder="Monto"/><input id="fs_day" type="number" placeholder="Día" min="1" max="31"/></div><button class="primary" onclick="L.addSub()">Agregar</button></div></div><div class="card"><h2>Suscripciones <span class="subtitle">${L.utils.formatCurrency(st)}</span></h2>${(f.subscriptions||[]).map(s=>`<div class="list-row"><div class="grow"><div class="t1">${L.utils.esc(s.name)}</div><div class="t2">Día ${s.day}</div></div><span>${L.utils.formatCurrency(s.price)}</span><button class="btn-icon" onclick="L.delSub('${L.utils.esc(s.name)}')">🗑</button></div>`).join("")}</div>`}else if(L.financeTab==="debts"){body=`<div class="card"><h2>Nueva deuda</h2><div class="form"><input id="fd_name" placeholder="Acreedor"/><div class="form-row"><input id="fd_amt" type="number" placeholder="Total"/><input id="fd_paid" type="number" placeholder="Pagado" value="0"/></div><button class="danger" onclick="L.addDebt()">Agregar</button></div></div><div class="card"><h2>Deudas <span class="subtitle">${L.utils.formatCurrency(dt)}</span></h2>${(f.debts||[]).map(d=>`<div class="list-row"><div class="grow"><div class="t1">${L.utils.esc(d.name)}</div><div class="t2">Pendiente ${L.utils.formatCurrency((d.amount||0)-(d.paid||0))}</div></div><button class="btn-icon" onclick="L.delDebt('${d.id}')">🗑</button></div>`).join("")}</div>`}else if(L.financeTab==="travel"){body=`<div class="card"><h2>Nuevo destino</h2><div class="form"><input id="tv_country" placeholder="País"/><input id="tv_city" placeholder="Ciudad"/><select id="tv_pri"><option value="Alta">🔴 Alta</option><option value="Media" selected>🟡 Media</option><option value="Baja">🟢 Baja</option></select><button class="primary" onclick="L.addTravel()">Agregar</button></div></div><div class="card"><h2>Destinos</h2>${(f.travel||[]).length===0?'<p class="empty">Sin viajes</p>':(f.travel||[]).map(d=>`<div class="list-row"><div class="grow"><div class="t1">🌍 ${L.utils.esc(d.country)}${d.city?' · '+L.utils.esc(d.city):''}</div><div class="t2">${d.status}</div></div>${L.badge(d.priority,d.priority==="Alta"?"danger":d.priority==="Media"?"warning":"success")}<button class="btn-icon" onclick="L.delTravel('${d.id}')">🗑</button></div>`).join("")}</div>`}else{body=`<div class="metric-grid">${L.metricHtml("Ingreso",L.utils.formatCurrency(f.monthlyIncome||0),100,"success")}${L.metricHtml("Gastos fijos",L.utils.formatCurrency(ft),L.utils.percent(ft,f.monthlyIncome||1),"danger")}${L.metricHtml("Balance",L.utils.formatCurrency(bal),50,bal<0?"danger":"success")}${L.metricHtml("Ahorros",L.utils.formatCurrency(svTotal),50,"primary")}</div><div class="card"><h2>Configuración</h2><div class="form"><div class="form-row"><div><label>Moneda</label><select id="fc_cur"><option value="COP" ${cur==='COP'?'selected':''}>COP</option><option value="USD" ${cur==='USD'?'selected':''}>USD</option><option value="EUR" ${cur==='EUR'?'selected':''}>EUR</option></select></div><div><label>Ingreso mensual</label><input id="fc_inc" type="number" value="${f.monthlyIncome||0}"/></div></div><button class="primary" onclick="L.saveFinCfg()">Guardar</button></div></div>`}r.innerHTML=tabs+body};
L.addFinMove=()=>{const t=document.getElementById("fm_concept").value.trim(),a=+document.getElementById("fm_amount").value||0,ty=document.getElementById("fm_type").value,catId=document.getElementById("fm_cat").value;if(!t)return;const f=L.state.finance;if(!f.movements)f.movements=[];f.movements.push({id:L.utils.uuid(),title:t,amount:a,type:ty,catId,date:L.utils.today()});L.save();L.router("finance")};
L.delFinMove=id=>{const f=L.state.finance;f.movements=(f.movements||[]).filter(m=>m.id!==id);L.save();L.router("finance")};
L.addFinCat=()=>{const icon=document.getElementById("fcat_icon").value.trim()||"📌",name=document.getElementById("fcat_name").value.trim();if(!name)return;L.state.finance.categories.push({id:L.utils.uuid(),name,icon});L.save();L.router("finance")};
L.delFinCat=id=>{L.state.finance.categories=L.state.finance.categories.filter(c=>c.id!==id);L.save();L.router("finance")};
L.addSaving=()=>{const name=document.getElementById("fsv_name").value.trim(),target=+document.getElementById("fsv_target").value||0,saved=+document.getElementById("fsv_saved").value||0;if(!name)return;L.state.finance.savingsGoals.push({id:L.utils.uuid(),name,target,saved});L.save();L.router("finance")};
L.addToSaving=id=>{const inp=document.getElementById("fsv_add_"+id),v=+inp.value||0;if(!v)return;const sv=L.state.finance.savingsGoals.find(s=>s.id===id);if(sv)sv.saved=(sv.saved||0)+v;L.save();L.router("finance")};
L.delSaving=id=>{L.state.finance.savingsGoals=L.state.finance.savingsGoals.filter(s=>s.id!==id);L.save();L.router("finance")};
L.addFixed=()=>{const n=document.getElementById("ff_name").value.trim(),p=+document.getElementById("ff_price").value||0,d=+document.getElementById("ff_day").value||1;if(!n)return;L.state.finance.fixedExpenses.push({name:n,price:p,day:d});L.save();L.router("finance")};
L.delFixed=name=>{L.state.finance.fixedExpenses=(L.state.finance.fixedExpenses||[]).filter(e=>e.name!==name);L.save();L.router("finance")};
L.addSub=()=>{const n=document.getElementById("fs_name").value.trim(),p=+document.getElementById("fs_price").value||0,d=+document.getElementById("fs_day").value||1;if(!n)return;L.state.finance.subscriptions.push({name:n,price:p,day:d});L.save();L.router("finance")};
L.delSub=name=>{L.state.finance.subscriptions=(L.state.finance.subscriptions||[]).filter(s=>s.name!==name);L.save();L.router("finance")};
L.addDebt=()=>{const n=document.getElementById("fd_name").value.trim(),a=+document.getElementById("fd_amt").value||0,p=+document.getElementById("fd_paid").value||0;if(!n)return;L.state.finance.debts.push({id:L.utils.uuid(),name:n,amount:a,paid:p});L.save();L.router("finance")};
L.delDebt=id=>{L.state.finance.debts=(L.state.finance.debts||[]).filter(d=>d.id!==id);L.save();L.router("finance")};
L.addTravel=()=>{const c=document.getElementById("tv_country").value.trim(),city=document.getElementById("tv_city").value.trim(),p=document.getElementById("tv_pri").value;if(!c)return;L.state.finance.travel.push({id:L.utils.uuid(),country:c,city,status:"Pendiente",priority:p});L.save();L.router("finance")};
L.delTravel=id=>{L.state.finance.travel=(L.state.finance.travel||[]).filter(x=>String(x.id)!==String(id));L.save();L.router("finance")};
L.saveFinCfg=()=>{const f=L.state.finance;f.currency=document.getElementById("fc_cur").value;f.monthlyIncome=+document.getElementById("fc_inc").value||0;L.save();L.router("finance")};
L.shopCatSel=L.shopCatSel||"Comida";
L.views.shopping=r=>{const items=L.state.shopping||[],pending=items.filter(i=>!i.bought).length,isFood=L.shopCatSel==="Comida";r.innerHTML=`<div class="card"><h2>Nuevo artículo</h2><div class="form"><input id="sh_name" placeholder="Producto"/><select id="sh_cat" onchange="L.shopCatSel=this.value;L.router('shopping')">${Object.keys(L.shopCat).map(c=>`<option value="${c}" ${L.shopCatSel===c?'selected':''}>${L.shopCat[c]} ${c}</option>`).join("")}</select><div class="form-row"><input id="sh_qty" placeholder="Cantidad" value="1"/><input id="sh_unit" placeholder="Unidad (opcional)"/></div><div class="form-row"><input id="sh_grams" type="number" placeholder="Gramos (opcional)"/><input id="sh_price" type="number" placeholder="Precio (opcional)"/></div>${isFood?`<p style="font-size:11px;color:var(--text3)">Datos nutricionales (opcional, se enlazan a Nutrición)</p><div class="form-row"><input id="sh_cal" type="number" placeholder="Calorías"/><input id="sh_prot" type="number" placeholder="Proteína (g)"/></div><div class="form-row"><input id="sh_carbs" type="number" placeholder="Carbs (g)"/><input id="sh_fat" type="number" placeholder="Grasa (g)"/></div>`:''}<button class="primary" onclick="L.addShop()">➕ Agregar</button></div></div><div class="card"><h2>Lista <span class="subtitle">${pending} pendientes</span></h2>${items.length===0?'<p class="empty">Vacía</p>':items.map(i=>`<div class="checkbox-row ${i.bought?'done':''}"><input type="checkbox" ${i.bought?'checked':''} onchange="L.toggleShop('${i.id}')"/><span class="clabel">${L.shopCat[i.category]||'📦'} ${L.utils.esc(i.name)} <span style="color:var(--text3)">· ${L.utils.esc(i.quantity)}${i.unit?' '+L.utils.esc(i.unit):''}${i.grams?' · '+i.grams+'g':''}${i.price?' · '+L.utils.formatCurrency(i.price):''}${i.calories?' · 🔥'+i.calories+'kcal':''}</span></span><button class="btn-icon" onclick="L.delShop('${i.id}')">🗑</button></div>`).join("")}${items.some(i=>i.bought)?`<button class="success" style="width:100%;margin-top:10px" onclick="L.moveShopToInv()">📦 Mover comprados a inventario</button>`:''}</div>`};
L.addShop=()=>{const n=document.getElementById("sh_name").value.trim(),cat=document.getElementById("sh_cat").value,q=document.getElementById("sh_qty").value.trim()||"1",unit=document.getElementById("sh_unit").value.trim(),grams=+document.getElementById("sh_grams").value||null,price=+document.getElementById("sh_price").value||null;if(!n)return;const item={id:L.utils.uuid(),name:n,category:cat,quantity:q,unit,grams,price,bought:false};if(cat==="Comida"){const cal=+document.getElementById("sh_cal")?.value||null,prot=+document.getElementById("sh_prot")?.value||null,carbs=+document.getElementById("sh_carbs")?.value||null,fat=+document.getElementById("sh_fat")?.value||null;if(cal)item.calories=cal;if(prot)item.protein=prot;if(carbs)item.carbs=carbs;if(fat)item.fat=fat}L.state.shopping.push(item);L.save();L.router("shopping")};
L.toggleShop=id=>{const i=L.state.shopping.find(x=>String(x.id)===String(id));if(!i)return;i.bought=!i.bought;if(i.bought&&i.price){const f=L.state.finance;if(!f.movements)f.movements=[];const catMap={Comida:"Comida",Aseo:"Hogar",Hogar:"Hogar",Salud:"Salud",Estudio:"Estudio",Otro:"Ocio"};const fcat=(f.categories||[]).find(c=>c.name===(catMap[i.category]||"Ocio"))||(f.categories||[])[0];f.movements.push({id:L.utils.uuid(),title:"🛒 "+i.name,amount:i.price,type:"expense",catId:fcat?.id||null,date:L.utils.today()});L.utils.toast("Gasto agregado a Finanzas")}L.save();L.router("shopping")};
L.delShop=id=>{L.state.shopping=L.state.shopping.filter(x=>String(x.id)!==String(id));L.save();L.router("shopping")};
L.moveShopToInv=()=>{const bought=L.state.shopping.filter(i=>i.bought);let foodsAdded=0;bought.forEach(i=>{const invItem={id:L.utils.uuid(),name:i.name,qty:isNaN(+i.quantity)?1:+i.quantity,unit:i.unit||"",category:i.category||"Otro"};L.state.inventory.push(invItem);if(i.category==="Comida"&&(i.calories||i.protein||i.carbs||i.fat)){const n=L.state.nutrition;if(!n.foods)n.foods=[];const existing=n.foods.find(f=>f.name.toLowerCase()===i.name.toLowerCase());if(existing){existing.calories=i.calories||existing.calories;existing.protein=i.protein||existing.protein;existing.carbs=i.carbs||existing.carbs;existing.fat=i.fat||existing.fat;existing.inventoryId=invItem.id}else{n.foods.push({id:L.utils.uuid(),name:i.name,calories:i.calories||0,protein:i.protein||0,carbs:i.carbs||0,fat:i.fat||0,inventoryId:invItem.id});foodsAdded++}}});L.state.shopping=L.state.shopping.filter(i=>!i.bought);L.save();L.utils.toast(`${bought.length} a inventario${foodsAdded?` · ${foodsAdded} a alimentos`:''}`);L.router("shopping")};
L.views.inventory=r=>{const items=L.state.inventory||[];r.innerHTML=`<div class="card"><h2>Nuevo objeto</h2><div class="form"><input id="in_name" placeholder="Nombre"/><select id="in_cat">${Object.keys(L.shopCat).map(c=>`<option value="${c}">${L.shopCat[c]} ${c}</option>`).join("")}</select><div class="form-row"><input id="in_qty" type="number" value="1"/><input id="in_unit" placeholder="Unidad (opcional)"/></div><button class="primary" onclick="L.addInv()">Guardar</button></div></div><div class="card"><h2>Inventario <span class="subtitle">${items.length} items</span></h2>${items.length===0?'<p class="empty">Vacío</p>':items.map(i=>`<div class="list-row"><div class="grow"><div class="t1">${L.shopCat[i.category]||'📦'} ${L.utils.esc(i.name)}</div><div class="t2">${i.qty}${i.unit?' '+L.utils.esc(i.unit):''}</div></div><button class="btn-icon" onclick="L.delInv('${i.id}')">🗑</button></div>`).join("")}</div>`};
L.addInv=()=>{const n=document.getElementById("in_name").value.trim(),cat=document.getElementById("in_cat").value,q=+document.getElementById("in_qty").value||1,unit=document.getElementById("in_unit").value.trim();if(!n)return;L.state.inventory.push({id:L.utils.uuid(),name:n,qty:q,unit,category:cat});L.save();L.router("inventory")};
L.delInv=id=>{L.state.inventory=L.state.inventory.filter(x=>x.id!==id);L.save();L.utils.toast("Eliminado del inventario");L.router("inventory")};
L.views.supplements=r=>{const supps=L.state.supplements||[];r.innerHTML=`<div class="card"><h2>Nuevo suplemento</h2><div class="form"><input id="sp_name" placeholder="Nombre (ej: Creatina)"/><div class="form-row"><input id="sp_dose" placeholder="Dosis (ej: 5g)"/><input id="sp_freq" placeholder="Frecuencia"/></div><input id="sp_time" type="time"/><button class="primary" onclick="L.addSupp()">Agregar</button></div></div><div class="card"><h2>Suplementos <span class="subtitle">${supps.length}</span></h2>${supps.length===0?'<p class="empty">Sin suplementos</p>':supps.slice().sort((a,b)=>(a.time||"").localeCompare(b.time||"")).map(s=>`<div class="list-row"><div style="width:52px;flex-shrink:0;text-align:center"><span class="badge badge-primary">${s.time||'--:--'}</span></div><div class="grow"><div class="t1">${L.utils.esc(s.name)}</div><div class="t2">${L.utils.esc(s.dose)} · ${L.utils.esc(s.frequency)}</div></div><button class="btn-icon" onclick="L.delSupp('${s.id}')">🗑</button></div>`).join("")}</div>`};
L.addSupp=()=>{const n=document.getElementById("sp_name").value.trim(),d=document.getElementById("sp_dose").value.trim(),f=document.getElementById("sp_freq").value.trim(),t=document.getElementById("sp_time").value;if(!n)return;if(!L.state.supplements)L.state.supplements=[];L.state.supplements.push({id:L.utils.uuid(),name:n,dose:d,frequency:f,time:t});L.save();L.router("supplements")};
L.delSupp=id=>{L.state.supplements=L.state.supplements.filter(s=>s.id!==id);L.save();L.router("supplements")};
L.views.skincare=r=>{const sk=L.state.skincare||{amSteps:[],pmSteps:[],log:{}},tk=L.utils.todayKey(),todayLog=sk.log[tk]||{am:[],pm:[]};const mkList=(steps,period)=>steps.length===0?'<p class="empty">Sin pasos</p>':steps.map((s,i)=>{const done=todayLog[period].includes(i);return`<div class="checkbox-row ${done?'done':''}"><input type="checkbox" ${done?'checked':''} onchange="L.toggleSkin('${period}',${i})"/><span class="clabel">${L.utils.esc(s)}</span><button class="btn-icon" onclick="L.delSkinStep('${period}',${i})">🗑</button></div>`}).join("");r.innerHTML=`<div class="card"><h2>☀️ Rutina mañana <span class="subtitle">${todayLog.am.length}/${sk.amSteps.length}</span></h2>${mkList(sk.amSteps,'am')}<div class="row" style="margin-top:8px"><input id="sk_am_new" placeholder="Nuevo paso"/><button class="btn-icon" style="background:var(--card3)" onclick="L.addSkinStep('am')">➕</button></div></div><div class="card"><h2>🌙 Rutina noche <span class="subtitle">${todayLog.pm.length}/${sk.pmSteps.length}</span></h2>${mkList(sk.pmSteps,'pm')}<div class="row" style="margin-top:8px"><input id="sk_pm_new" placeholder="Nuevo paso"/><button class="btn-icon" style="background:var(--card3)" onclick="L.addSkinStep('pm')">➕</button></div></div>`};
L.toggleSkin=(period,idx)=>{const sk=L.state.skincare,tk=L.utils.todayKey();if(!sk.log[tk])sk.log[tk]={am:[],pm:[]};const arr=sk.log[tk][period];const i=arr.indexOf(idx);if(i>=0)arr.splice(i,1);else arr.push(idx);L.save();L.router("skincare")};
L.addSkinStep=(period)=>{const inp=document.getElementById(`sk_${period}_new`),v=inp.value.trim();if(!v)return;L.state.skincare[period+"Steps"].push(v);L.save();L.router("skincare")};
L.delSkinStep=(period,idx)=>{L.state.skincare[period+"Steps"].splice(idx,1);L.save();L.router("skincare")};
L.views.hair=r=>{const h=L.state.hair||{steps:[]};r.innerHTML=`<div class="card"><h2>Rutina cabello</h2><div class="form"><input id="hr_step" placeholder="Paso (ej: Champú)"/><select id="hr_period"><option value="Lavado">🚿 Lavado</option><option value="Tratamiento">✨ Tratamiento</option><option value="Diario">📅 Diario</option></select><button class="primary" onclick="L.addHairStep()">Agregar</button></div></div><div class="card"><h2>Pasos</h2>${(h.steps||[]).length===0?'<p class="empty">Sin pasos</p>':(h.steps||[]).map((s,i)=>`<div class="list-row"><div class="grow"><div class="t1">${L.utils.esc(s.name)}</div><div class="t2">${s.period}</div></div><button class="btn-icon" onclick="L.delHairStep(${i})">🗑</button></div>`).join("")}</div>`};
L.addHairStep=()=>{const n=document.getElementById("hr_step").value.trim(),p=document.getElementById("hr_period").value;if(!n)return;L.state.hair.steps.push({name:n,period:p});L.save();L.router("hair")};
L.delHairStep=i=>{L.state.hair.steps.splice(i,1);L.save();L.router("hair")};
L.views.developer=r=>{const dev=L.state.developer||{};r.innerHTML=`<div class="card"><h2>Modo Developer</h2><div class="row-between" style="padding:10px 0;border-bottom:1px solid #2a313c"><span style="font-size:13px;font-weight:600">Developer Mode</span><div class="toggle-switch ${dev.developerMode?'active':''}" onclick="L.toggleDevMode()"></div></div><div class="row-between" style="padding:10px 0"><span style="font-size:13px;font-weight:600">Auto-guardado</span><div class="toggle-switch ${dev.autoSave?'active':''}" onclick="L.toggleAutoSave()"></div></div></div><div class="card"><h2>📁 Proyecto actual</h2><div class="form"><input id="dev_proj" value="${L.utils.esc(dev.currentProject||'')}"/><button class="primary" onclick="L.saveDevProj()">Actualizar</button></div></div><div class="card"><h2>📚 Aprendizaje</h2><div class="form"><input id="dev_learn" placeholder="Nuevo tema"/><button class="primary" onclick="L.addLearning()">Agregar</button></div><div style="margin-top:8px">${(dev.learning||[]).map((l,i)=>`<div class="list-row"><span class="grow t1">▸ ${L.utils.esc(l)}</span><button class="btn-icon" onclick="L.delLearning(${i})">🗑</button></div>`).join("")}</div></div><div class="card"><h2>🚀 Proyectos</h2><div class="form"><input id="dp_name" placeholder="Nombre"/><select id="dp_status"><option value="En desarrollo">En desarrollo</option><option value="Planificación">Planificación</option><option value="Completado">Completado</option><option value="Pausado">Pausado</option></select><input id="dp_prog" type="number" placeholder="Progreso %" min="0" max="100" value="0"/><button class="primary" onclick="L.addDevProject()">Agregar</button></div><div style="margin-top:10px">${(dev.projects||[]).map((pr,i)=>`<div class="exercise-card" style="flex-direction:column;align-items:stretch"><div class="row-between"><span style="font-weight:600;font-size:14px">${L.utils.esc(pr.name)}</span>${L.badge(pr.status,pr.status==="Completado"?"success":"primary")}</div><div style="margin:8px 0">${L.utils.bar(pr.progress,"primary")}</div><div class="row"><button class="ghost btn-sm" onclick="L.updateProj(${i},-10)">-10%</button><button class="ghost btn-sm" onclick="L.updateProj(${i},10)">+10%</button><button class="btn-icon" style="margin-left:auto" onclick="L.delProj(${i})">🗑</button></div></div>`).join("")}</div></div><div class="card"><h2>🛠️ Herramientas</h2><button class="warning" style="width:100%;margin-bottom:8px" onclick="L.exportData()">📤 Exportar JSON</button><button class="primary" style="width:100%;margin-bottom:8px" onclick="L.importDataPrompt()">📥 Importar JSON</button><button class="danger" style="width:100%" onclick="L.clearData()">💥 Borrar datos</button></div>`};
L.toggleDevMode=()=>{L.state.developer.developerMode=!L.state.developer.developerMode;L.save();L.router("developer")};
L.toggleAutoSave=()=>{L.state.developer.autoSave=!L.state.developer.autoSave;L.save();L.router("developer")};
L.saveDevProj=()=>{L.state.developer.currentProject=document.getElementById("dev_proj").value;L.save();L.router("developer")};
L.addLearning=()=>{const t=document.getElementById("dev_learn").value.trim();if(!t)return;if(!L.state.developer.learning)L.state.developer.learning=[];L.state.developer.learning.push(t);L.save();L.router("developer")};
L.delLearning=i=>{L.state.developer.learning.splice(i,1);L.save();L.router("developer")};
L.addDevProject=()=>{const n=document.getElementById("dp_name").value.trim(),s=document.getElementById("dp_status").value,p=+document.getElementById("dp_prog").value||0;if(!n)return;if(!L.state.developer.projects)L.state.developer.projects=[];L.state.developer.projects.push({name:n,status:s,progress:p});L.save();L.router("developer")};
L.updateProj=(i,d)=>{const pr=L.state.developer.projects[i];if(pr){pr.progress=Math.max(0,Math.min(100,(pr.progress||0)+d));if(pr.progress===100)pr.status="Completado"}L.save();L.router("developer")};
L.delProj=i=>{L.state.developer.projects.splice(i,1);L.save();L.router("developer")};
L.views.settings=r=>{const s=L.state.settings||{},m=L.state.metadata||{};r.innerHTML=`<div class="card"><h2>⚙️ General</h2><div class="row-between" style="padding:10px 0;border-bottom:1px solid #2a313c"><span style="font-size:13px;font-weight:600">Notificaciones</span><button class="btn-sm ghost" onclick="L.reqNotif()">${typeof Notification!=="undefined"&&Notification.permission==="granted"?"✅ Activas":"Activar"}</button></div><div class="row-between" style="padding:10px 0"><span style="font-size:13px;font-weight:600">Idioma</span><select id="set_lang" onchange="L.changeLang()" style="width:auto"><option value="es" ${s.language==='es'?'selected':''}>🇪🇸 ES</option><option value="en" ${s.language==='en'?'selected':''}>🇺🇸 EN</option></select></div></div><div class="card"><h2>💾 Datos</h2><button class="warning" style="width:100%;margin-bottom:8px" onclick="L.exportData()">📤 Exportar</button><button class="danger" style="width:100%" onclick="L.clearData()">💥 Borrar todo</button></div><div class="card"><h2>ℹ️ Sistema</h2><p style="font-size:13px;margin-bottom:3px"><strong>Versión:</strong> ${m.version||"2.0.0"}</p><p style="font-size:13px;margin-bottom:3px"><strong>Actualizado:</strong> ${m.lastUpdate||"N/A"}</p><p style="font-size:13px"><strong>Persistencia:</strong> LocalStorage</p></div>`};
L.toggleDarkMode=()=>{};
L.changeLang=()=>{L.state.settings.language=document.getElementById("set_lang").value;L.save()};
L.exportData=()=>{const blob=new Blob([JSON.stringify(L.state,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`lifeos-backup-${new Date().toISOString().split("T")[0]}.json`;a.click();URL.revokeObjectURL(url);L.save()};
L.importDataPrompt=()=>{const input=document.createElement("input");input.type="file";input.accept=".json";input.onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=ev=>{try{const data=JSON.parse(ev.target.result);L.state=L.mergeDeep(JSON.parse(JSON.stringify(L.profile)),data);L.migrate();L.save();L.utils.toast("✅ Importado");L.router("dashboard")}catch(err){L.utils.toast("❌ Error al importar")}};reader.readAsText(file)};input.click()};
L.clearData=()=>{if(!confirm("¿Eliminar TODOS los datos?"))return;localStorage.removeItem("lifeos_state");L.state=JSON.parse(JSON.stringify(L.profile));L.migrate();L.router("dashboard")};
L.config.viewMap.calendar={icon:"🗓️",title:"Calendario"};
L.calYear=new Date().getFullYear();L.calMonth=new Date().getMonth();L.calSelectedDay=L.utils.todayKey();
L.views.calendar=r=>{const y=L.calYear,m=L.calMonth,first=new Date(y,m,1),startDow=(first.getDay()+6)%7,daysInMonth=new Date(y,m+1,0).getDate();const monthNames=["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];const tasks=L.state.tasks||[],fixed=L.state.finance?.fixedExpenses||[],tk=L.utils.todayKey(),mk=`${y}-${String(m+1).padStart(2,'0')}`;let cells="";for(let i=0;i<startDow;i++)cells+='<div class="cal-day empty"></div>';for(let d=1;d<=daysInMonth;d++){const ds=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const hasTask=tasks.some(t=>t.due===ds&&!t.done),hasPay=fixed.some(e=>e.day===d),hasEvt=L.calEvents().events.some(ev=>ev.date===ds);let cls="cal-day";if(ds===tk)cls+=" today";if(ds===L.calSelectedDay)cls+=" selected";cells+=`<div class="${cls}" onclick="L.calSelectDay('${ds}')">${d}<div class="cal-dots">${hasTask?'<span class="cal-dot task"></span>':''}${hasPay?'<span class="cal-dot pay"></span>':''}${hasEvt?'<span class="cal-dot evt"></span>':''}</div></div>`}const selDay=+L.calSelectedDay.split('-')[2],selTasks=tasks.filter(t=>t.due===L.calSelectedDay),selPays=fixed.filter(e=>e.day===selDay),selEvts=L.calEvents().events.filter(e=>e.date===L.calSelectedDay);r.innerHTML=`<div class="card"><div class="cal-nav"><button onclick="L.calNav(-1)">‹</button><span style="font-weight:700">${monthNames[m]} ${y}</span><button onclick="L.calNav(1)">›</button></div><div class="cal-grid">${["L","M","X","J","V","S","D"].map(d=>`<div class="cal-dow">${d}</div>`).join("")}${cells}</div></div><div class="card"><h2>${L.calSelectedDay}</h2>${selTasks.length===0&&selPays.length===0&&selEvts.length===0?'<p class="empty">Sin eventos</p>':''}${selEvts.map(e=>`<div class="list-row"><span class="grow t1">${e.icon||'🔔'} ${L.utils.esc(e.title)}${e.time?' · '+e.time:''}</span><button class="btn-icon" onclick="L.delCalEvent('${e.id}')">🗑</button></div>`).join("")}${selTasks.map(t=>`<div class="checkbox-row ${t.done?'done':''}"><input type="checkbox" ${t.done?'checked':''} onchange="L.toggleTask('${t.id}')"/><span class="clabel">${L.taskCatIcon[t.category]||"📌"} ${L.utils.esc(t.title)}${t.dueTime?' · '+t.dueTime:''}</span></div>`).join("")}${selPays.map(e=>{const paid=(e.paidMonths||[]).includes(mk);return`<div class="pay-row"><span style="flex:1;font-size:14px">💳 ${L.utils.esc(e.name)}</span><span style="font-size:12px;color:var(--text3)">${L.utils.formatCurrency(e.price)}</span><button class="btn-sm ${paid?'success':'ghost'}" onclick="L.toggleExpensePaid('${L.utils.esc(e.name)}')">${paid?'✅ Pagado':'Pendiente'}</button></div>`}).join("")}</div><div class="card"><h2>➕ Nuevo evento</h2><div class="form"><input id="ce_title" placeholder="Título"/><div class="form-row"><input id="ce_date" type="date" value="${L.calSelectedDay}"/><input id="ce_time" type="time"/></div><input id="ce_icon" placeholder="Emoji (opcional)" maxlength="4"/><button class="primary" onclick="L.addCalEvent()">Agregar evento</button></div></div>`};
L.calNav=d=>{L.calMonth+=d;if(L.calMonth<0){L.calMonth=11;L.calYear--}if(L.calMonth>11){L.calMonth=0;L.calYear++}L.router('calendar')};
L.calSelectDay=ds=>{L.calSelectedDay=ds;L.router('calendar')};
L.addCalEvent=()=>{const t=document.getElementById("ce_title").value.trim();if(!t)return;const d=document.getElementById("ce_date").value||L.calSelectedDay,tm=document.getElementById("ce_time").value,ic=document.getElementById("ce_icon").value.trim()||"🔔";L.calEvents().events.push({id:L.utils.uuid(),title:t,date:d,time:tm,icon:ic,notified:false});L.save();L.router('calendar')};
L.delCalEvent=id=>{L.calEvents().events=L.calEvents().events.filter(e=>e.id!==id);L.save();L.router('calendar')};
L.toggleExpensePaid=name=>{const e=(L.state.finance.fixedExpenses||[]).find(x=>x.name===name);if(!e)return;if(!e.paidMonths)e.paidMonths=[];const mk=`${L.calYear}-${String(L.calMonth+1).padStart(2,'0')}`;const i=e.paidMonths.indexOf(mk);if(i>=0)e.paidMonths.splice(i,1);else e.paidMonths.push(mk);L.save();L.router('calendar')};
L.init=async()=>{await L.loadProfile();L.buildBottomNav();document.getElementById("headerDate").textContent=new Date().toLocaleDateString("es-ES",{weekday:"long",day:"numeric",month:"long"});L.router("dashboard");if(typeof Notification!=="undefined"&&Notification.permission==="granted")L.startNotifLoop()};
L.init();
